          docComment: 'Contains 0+× UserAttribute.',
          extra: [SomMetaExtra(annotation: 'StandardReferences', args: {'standards': ['SCIM 2.0 (RFC 7643/7644) — cross-domain identity provisioning'], 'connotation': 'The catalog of user attribute entries.'})],
          elementNode: _cx('UserAttributeEntry', s, _mc$UserAttributeEntry, (r, c) => SomMetaNode(className: 'UserAttributeEntry', classSectionId: 'USATE', kind: SomMetaKind.complex, typeName: 'UserAttributeEntry', docComment: 'A user attribute entry (form).', classDocComment: 'A user attribute entry (form).', recursive: r, children: c))),
